function sound38(status='pending'){if(!audio38||audio38.state!=='running')return;const notes=melodies385[status]||melodies385.confirmed;const negative=['cancelled','no_show'].includes(status);notes.forEach((hz,i)=>{const o=audio38.createOscillator(),g=audio38.createGain(),t=audio38.currentTime+i*(negative?.22:.13);o.type='sine';o.frequency.value=hz;o.connect(g);g.connect(audio38.destination);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.13,t+.025);g.gain.exponentialRampToValueAtTime(.001,t+.25);o.start(t);o.stop(t+.26);});}
