async function catalogDelete80(t,x){const org=current.id,g=generation;if(!confirm('Excluir '+x.name+'?'))return;const [p,s,r,m,b]=await Promise.all(['professionals','services','rewardItems','milestones','bookingRequests'].map(k=>getDocsFromServer(collection(db,'establishments',org,k))));if(g!==generation||current?.id!==org)return;const linked=t==='category'?[...s.docs,...r.docs].some(d=>d.data().categoryId===x.id):t==='service'?p.docs.some(d=>(d.data().serviceIds||[]).includes(x.id))||s.docs.some(d=>(d.data().comboParts||[]).includes(x.id))||b.docs.some(d=>d.data().service===x.id)||m.docs.some(d=>d.data().type==='service'&&d.data().itemId===x.id):m.docs.some(d=>d.data().type===t&&d.data().itemId===x.id);if(linked)throw Error('Cadastro vinculado a outros registros. Desative ou remova os vínculos antes de excluir.');await deleteDoc(doc(db,'establishments',org,t==='category'?'categories':t==='service'?'services':'rewardItems',x.id));if(g!==generation||current?.id!==org)return;openCatalog471('');await refresh();await loadMilestones64();renderCatalog80();}
for(const b of document.querySelectorAll('[data-quick80]'))b.onclick=()=>{openCatalog471('');rewardEdit80=null;quickType80=b.dataset.quick80;$('quick80').reset();$('quick80').hidden=false;$('quickLabel80').textContent='Nome — '+catalogTypes80[quickType80];$('quickName80').maxLength=quickType80==='category'?80:quickType80==='service'?100:180;$('quickName80').focus();};
$('quickCancel80').onclick=()=>$('quick80').hidden=true;
$('quick80').onsubmit=e=>{e.preventDefault();run(async()=>{const org=current?.id,g=generation,t=quickType80,name=$('quickName80').value.trim();if(!org||!unitAllowed21||!name)throw Error('Informe o nome.');if(catalogList80(t).some(x=>x.name.toLowerCase()===name.toLowerCase()))throw Error('Nome já cadastrado.');const kind=t==='category'?'categories':t==='service'?'services':'rewardItems';const data=t==='category'?{name}:t==='service'?{name,categoryId:'',priceCents:0,duration:5,active:false,comboParts:[],createdAt:serverTimestamp()}:{name,type:t,categoryId:'',description:'',eligible:false,draft:true,...(t==='product'?{priceCents:0}:{discountMode:'percent',discountValue:1})};await setDoc(doc(collection(db,'establishments',org,kind)),data);if(g!==generation||current?.id!==org)return;$('quick80').hidden=true;catalogTab80=t;await refresh();await loadMilestones64();renderCatalog80();$('status').textContent='Cadastro salvo. Use o lápis para completar.';});};
for(const t of ['product','coupon'])$(t+'70').onsubmit=e=>{e.preventDefault();run(async()=>{const org=current?.id,g=generation,edit=rewardEdit80;if(!org||!unitAllowed21||!edit||edit.org!==org)return;const name=$(t+'Name70').value.trim();if(!name)throw Error('Informe o nome.');const data={name,type:t,categoryId:$(t+'Category70').value,description:$(t+'Desc70').value.trim(),eligible:$(t+'Eligible70').checked,draft:false};if(t==='product')data.priceCents=Math.round(Number($('productPrice70').value)*100);else{data.discountMode=$('couponMode70').value;data.discountValue=Number($('couponValue70').value);if(data.discountMode==='percent'&&data.discountValue>100)throw Error('Desconto máximo de 100%.');}await updateDoc(doc(rewardCollection64(org,'rewardItems'),edit.id),data);if(g!==generation||current?.id!==org)return;rewardEdit80=null;openCatalog471('');await loadMilestones64();$('status').textContent='Alterações salvas!';});};
$('catalogSearch80').oninput=renderCatalog80;

for(const id of Object.values(catalogForms80)){const f=$(id),b=node395("button","Fechar edição");b.type="button";b.className="secondary";b.onclick=()=>{rewardEdit80=null;openCatalog471("");};f.append(b);}

function renderManagerHistory(rows){
 const root=$('requests');root.replaceChildren();
 if(!rows.length){root.textContent='Nenhum registro encontrado.';return;}
 const labels=['Data','Horário','Nome do cliente','WhatsApp','Nome do barbeiro','Status'];
 const wrap=document.createElement('div');wrap.className='manager-history82';
 const table=document.createElement('table'),head=table.createTHead().insertRow(),body=table.createTBody();
 for(const label of labels){const th=document.createElement('th');th.scope='col';th.textContent=label;head.append(th);}
 for(const x of [...rows].sort((a,b)=>`${b.date||''}T${b.time||''}`.localeCompare(`${a.date||''}T${a.time||''}`))){
 const tr=body.insertRow();const values=[/^\d{4}-\d{2}-\d{2}$/.test(x.date||'')?x.date.split('-').reverse().join('/'):x.date||'—',x.time||'—',x.name||'—',x.phone||'—',pros.find(p=>p.id===x.professional)?.name||x.professionalName||'Profissional não identificado',statusNames[x.status]||'Status desconhecido'];
 values.forEach((v,i)=>{const td=tr.insertCell();td.dataset.label=labels[i];td.textContent=v;if(i===3){const digits=String(x.phone||'').replace(/\D/g,'');const number=[10,11].includes(digits.length)?'55'+digits:/^55\d{10,11}$/.test(digits)?digits:'';if(number){const link=document.createElement('a');link.href='https://wa.me/'+number;link.target='_blank';link.rel='noopener noreferrer';link.textContent=v;td.replaceChildren(link);}}if(i===5)td.dataset.status=x.status||'';});
 }wrap.append(table);root.append(wrap);
}
